                c = routes[i][a]
                for j in range(len(routes)):
                    if i == j:
                        continue
                    if load(routes[j]) + dem(c) > cap:
                        continue
                    base = cost(routes[i]) + cost(routes[j])
                    ri = routes[i][:a] + routes[i][a + 1:]
                    for pos in range(len(routes[j]) + 1):
                        rj = routes[j][:pos] + [c] + routes[j][pos:]
                        if load(ri) <= cap and load(rj) <= cap:
                            nc = cost(ri) + cost(rj)
                            if nc + 1e-12 < base:
                                routes[i], routes[j] = ri, rj
                                improved = True
                                break
                    if improved:
                        break
                if improved:
                    break
            if improved:
                break

    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    routes = [r for r in routes if r]
    missing = [c for c in customers if seen.get(c, 0) == 0]
    if missing:
        for c in missing:
            best = None
            bestm = None
            for ri, r in enumerate(routes):
                if load(r) + dem(c) > cap:
                    continue
                for pos in range(len(r) + 1):
                    m = (ins_cost(r, pos, c), len(r), ri, pos)
                    if bestm is None or m < bestm:
                        bestm = m
                        best = (ri, pos)
            if best is None:
                routes.append([c])
            else:
                routes[best[0]].insert(best[1], c)

    return routes
